const telescope = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); for (let k = 0; k < 3; k++) { const a = (k / 3) * TAU; limb([[0, 1.1, 0], [Math.cos(a) * 0.35, 0, Math.sin(a) * 0.35]], 0.025, 0.02, mk().M.bark, { seg: 3, rad: 5, parent: G }); } const t = grp(0, 1.15, 0, 0, G); t.rotation.x = -0.4; add(olathe([[0.001, -0.5], [0.06, -0.5], [0.08, 0.2], [0.11, 0.55], [0.001, 0.55]], 14), std({ map: goldTex(), metalness: 1, roughness: 0.3 }), [0, 0, 0], [0, 0, 0], null, t); return G; };
const ropeRail = (pts, h = 0.85) => { const M0 = mk().M; pts.forEach(([x, z]) => { limb([[x, 0, z], [x, h, z]], 0.06, 0.05, M0.bark, { seg: 3, rad: 5 }); }); for (let i = 0; i < pts.length - 1; i++) tube([[pts[i][0], h - 0.1, pts[i][1]], [(pts[i][0] + pts[i + 1][0]) / 2, h - 0.25, (pts[i][1] + pts[i + 1][1]) / 2], [pts[i + 1][0], h - 0.1, pts[i + 1][1]]], 0.02, M0.rope, 6); };
