const pulseRings = (X, Y, lx, ly) => PAINT.push(Object.assign(() => {}, { glow: (g, sx, sy, S) => { if (sx !== X || sy !== Y) return; g.strokeStyle = "rgba(90,200,255,0.55)"; for (let k = 1; k < 6; k++) { g.lineWidth = S * 0.12; g.beginPath(); g.arc(lx * S, ly * S, k * 3.6 * S, 0, TAU); g.stroke(); } } }));
// ================= WILD DRESSING: the detail layer for every Part 2 scene =================
const mistT = () => MK.mistT || (MK.mistT = tex(256, 256, (g, W) => { for (let k = 0; k < 26; k++) { const x = 50 + R() * 156, y = 50 + R() * 156, rr = 30 + R() * 50, gr = g.createRadialGradient(x, y, 0, x, y, rr); gr.addColorStop(0, "rgba(255,255,255,0.16)"); gr.addColorStop(1, "rgba(255,255,255,0)"); g.fillStyle = gr; g.fillRect(0, 0, W, W); } }));
