const rootM = () => MK.rootM || (MK.rootM = std({ map: MK.barkT, color: "#e0c0a0", roughness: 0.9, emissive: "#3a2a1a", emissiveIntensity: 0.5 }));
const rootTangle = (x, z, s = 1) => { const M0 = mk().M; for (let k = 0; k < 6; k++) { const a = R() * TAU, L = (1.2 + R() * 1.6) * s, hh = (0.4 + R() * 0.9) * s, b = a + (R() - 0.5) * 1.2; limb([[x + Math.cos(a) * L, -0.2, z + Math.sin(a) * L], [x + Math.cos(a) * L * 0.4, hh, z + Math.sin(a) * L * 0.4], [x - Math.cos(b) * L * 0.4, hh * 0.8, z - Math.sin(b) * L * 0.4], [x - Math.cos(b) * L, -0.2, z - Math.sin(b) * L]], 0.16 * s, 0.09 * s, rootM(), { seg: 16, rad: 6, knob: 0.4 }); } glowcaps(x, z, 5, undefined, 1.2 * s); if (R() < 0.5) { const m = add(BUSHG(), M0.moss, [x, 0.5 * s, z], [R(), R(), R()]); m.scale.set(0.7 * s, 0.25 * s, 0.7 * s); } };
const bramble = (x, z, s = 1) => { const bm = MK.bramM || (MK.bramM = std({ color: "#3a1f4a", roughness: 0.8 })); for (let k = 0; k < 7; k++) { const a = R() * TAU, L = (1.0 + R() * 1.4) * s, hh = (0.8 + R() * 1.6) * s, pts = [[x + Math.cos(a) * 0.3, -0.1, z + Math.sin(a) * 0.3], [x + Math.cos(a) * L * 0.5, hh, z + Math.sin(a) * L * 0.5], [x + Math.cos(a + 0.6) * L, hh * 0.6, z + Math.sin(a + 0.6) * L], [x + Math.cos(a + 1.1) * L * 1.2, 0.1, z + Math.sin(a + 1.1) * L * 1.2]]; limb(pts, 0.09 * s, 0.03 * s, bm, { seg: 14, rad: 5, knob: 0.5 }); for (let q = 0; q < 3; q++) { const p = pts[1 + (q % 2)]; add(new THREE.ConeGeometry(0.035, 0.22, 4), MK.glowC("#c86aff", 1.6), [p[0] + (R() - 0.5) * 0.5, p[1] + (R() - 0.3) * 0.4, p[2] + (R() - 0.5) * 0.5], [R() * 3, 0, R() * 3]); } if (k % 2) add(new THREE.SphereGeometry(0.08, 8, 6), MK.glowC("#ff6ad8", 1.8), [pts[2][0], pts[2][1], pts[2][2]]); } };
const puffField = (x, z, r = 2, n = 8) => { for (let k = 0; k < n; k++) { const a = R() * TAU, rr = Math.sqrt(R()) * r, s = 0.14 + R() * 0.26; add(warp(new THREE.SphereGeometry(s, 10, 8), s * 0.06, 2), MK.puffM || (MK.puffM = std({ color: "#f4ecd8", emissive: "#fff0b0", emissiveIntensity: 0.4, roughness: 0.9 })), [x + Math.cos(a) * rr, s * 0.8, z + Math.sin(a) * rr]); } };
const cairn = (x, z) => { const M0 = mk().M; let y = 0; for (let k = 0; k < 4; k++) { const s = 0.34 - k * 0.07; boulder(x + (R() - 0.5) * 0.06, y + s * 0.5, z + (R() - 0.5) * 0.06, s, M0.stone, 0.5); y += s * 0.8; } add(new THREE.SphereGeometry(0.07, 8, 6), MK.glowC("#c8f06a", 2), [x, y + 0.1, z]); };
const mossRock = (x, z, s = 1) => { const M0 = mk().M; boulder(x, 0.25 * s, z, 0.6 * s, M0.stone, 0.55); const m = add(BUSHG(), M0.moss, [x, 0.6 * s, z], [R(), R(), R()]); m.scale.set(0.55 * s, 0.16 * s, 0.55 * s); if (R() < 0.5) glowcaps(x + 0.6 * s, z + 0.3 * s, 3); };
const vineDrape = (x0, z0, x1, z1, h = 4.5, c) => { const M0 = mk().M, pts = [], n = 9; for (let k = 0; k <= n; k++) { const t = k / n; pts.push(new THREE.Vector3(x0 + (x1 - x0) * t, h - Math.sin(Math.PI * t) * 1.3, z0 + (z1 - z0) * t)); } add(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts), 20, 0.03, 4), M0.leaf); for (let k = 1; k < n; k++) { const L = 0.2 + R() * 0.6; add(new THREE.CylinderGeometry(0.008, 0.008, L, 3), M0.rope, [pts[k].x, pts[k].y - L / 2, pts[k].z]); add(new THREE.SphereGeometry(0.07, 8, 6), MK.glowC(c || ["#3ff0ff", "#c8ff6a", "#ff7ad8", "#ffd27a"][k % 4], 2), [pts[k].x, pts[k].y - L, pts[k].z]); } };
const trailSign = (x, z, ry = 0) => { const M0 = mk().M, G = grp(x, 0, z, ry); limb([[0, 0, 0], [0.03, 1.0, 0], [0, 1.9, 0]], 0.06, 0.05, M0.bark, { seg: 5, rad: 5, parent: G }); for (const [y, r2] of [[1.6, 0.2], [1.25, -2.6]]) { const s = new THREE.Shape(); s.moveTo(-0.5, -0.13); s.lineTo(0.35, -0.13); s.lineTo(0.55, 0); s.lineTo(0.35, 0.13); s.lineTo(-0.5, 0.13); s.closePath(); add(new THREE.ExtrudeGeometry(s, { depth: 0.04, bevelEnabled: false }), M0.plank, [0, y, 0.05], [0, r2, 0], null, G); } add(new THREE.SphereGeometry(0.07, 8, 6), MK.glowC("#ffd27a", 1.8), [0, 2.0, 0], [0, 0, 0], null, G); };
const wildDress = (X, Y, o = {}) => { const BR = o.noTangle ? (x, z, sc) => (R() < 0.5 ? yColumn(x, z, 1 + R() * 2.4) : mossRock(x, z, sc)) : bramble; const RT = o.noTangle ? (x, z, sc) => mossRock(x, z, sc * 0.7) : rootTangle; const near = (x, z) => { for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1], [2, 0], [-2, 0], [0, 2], [0, -2]]) if ("pPk".includes(at(x + dx, z + dz))) return true; return false; }; const talls = [];
  for (let y = 1; y < 29; y++) for (let x = 1; x < 29; x++) { const c = at(X + x, Y + y), px = X + x + R(), pz = Y + y + R(), q = R(); if (c === "." || c === "g") { const nr = near(X + x, Y + y); if (c === "." && nr) { if (q < 0.035) RT(px, pz, 0.7 + R() * 0.5); else if (q < 0.07) mossRock(px, pz, 0.6 + R() * 0.7); else if (q < 0.095) puffField(px, pz, 1.2, 6); else if (q < 0.11) cairn(px, pz); else if (q < 0.125) logP(px, pz, 1.8 + R() * 1.4, R() * 3); } else if (c === "." && q < 0.03) { RT(px, pz, 1 + R() * 0.8); talls.push([px, pz]); } else if (c === "." && q < 0.05) puffField(px, pz, 2, 9); else if (c === "g" && q < 0.012) mossRock(px, pz, 0.8); }
    else if (c === "x") { if (q < 0.1) BR(px, pz, 0.9 + R() * 0.8); else if (q < 0.14) { RT(px, pz, 1.2 + R()); talls.push([px, pz]); } else if (q < 0.19) mossRock(px, pz, 1 + R()); }
    else if (c === "w") { if (q < (o.mist || 0.012)) mistBank(px, pz, 4 + R() * 4); else if (q < (o.mist || 0.012) + 0.008) frogspawn(px, pz); } }
  // colossal background mushrooms deep in the closed areas, and lantern posts along every path
  for (let y = 2; y < 28; y++) for (let x = 2; x < 28; x++) { const c = at(X + x, Y + y); if ((c === "x" || c === ".") && distW(X + x, Y + y) >= 6 && R() < (o.giants ?? 0.022)) giantMush(X + x + R(), Y + y + R(), 10 + R() * 8, 3.2 + R() * 2.4, ["#3fe0d0", "#7a3fa0", "#b06ad8", "#3fa0e0", "#ffb347"][Math.floor(R() * 5)], (R() - 0.5) * 0.1, 1);
    if (c === "." && (x * 7 + y * 13) % 9 === 0) { let ed = false; for (const [dx, dz] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if ("pP".includes(at(X + x + dx, Y + y + dz))) ed = true; if (ed) sporeLantern(X + x + 0.5, Y + y + 0.5, 2.1 + R() * 0.4, o.lampC || "#c8fff0"); } }
  for (let k = 0; k < (o.shafts ?? 6); k++) { const x = X + 2 + R() * 26, z = Y + 2 + R() * 26; if (".gx".includes(at(x | 0, z | 0))) lightShaft(x, z, 9 + R() * 8, ["#bfe8ff", "#e0c8ff", "#c8ffe0"][k % 3]); }
  for (let k = 0; k + 1 < talls.length && k < 16; k += 2) { const [a, b] = [talls[k], talls[k + 1]]; if (Math.hypot(a[0] - b[0], a[1] - b[1]) < 12) { let ok = true; for (let t = 0; t <= 1; t += 0.1) if ("pPk".includes(at(Math.floor(a[0] + (b[0] - a[0]) * t), Math.floor(a[1] + (b[1] - a[1]) * t)))) ok = false; if (ok && !o.noTangle) vineDrape(a[0], a[1], b[0], b[1], 3.6 + R() * 1.5); } } };
// ================= WILDLIFE: tall-grass encounter patches, nests, burrows and feeding spots =================
// tallGrass() lays a patch of tall swaying blades and records it as an encounter zone; the game spawns wild
// Alienmon that roam inside the patch and can pop out of the grass when Rook walks through.
const TG = [], TGP = [];
const TGK = { // blade colours (root -> tip), seed-head glow, and who lives there
  meadow: { lo: "#1e5a2a", hi: "#b8f07a", seed: "#e8ff9a", mons: ["lo_sporix", "lo_chirpod", "lo_blinkit"] },
  fen: { lo: "#1a4a4a", hi: "#7ae0c8", seed: "#9af0ff", mons: ["lo_gloopa", "lo_mycora", "lo_gloopa"] },
  spore: { lo: "#4a2a5a", hi: "#ff9ad8", seed: "#ffd0f0", mons: ["lo_dreamcap", "lo_blinkit", "lo_sporix"] },
  ember: { lo: "#5a3a1a", hi: "#ffc860", seed: "#fff0a0", mons: ["lo_chirpod", "lo_pebblet", "lo_sporix"] },
  rocky: { lo: "#3a4a3a", hi: "#a8c890", seed: "#d8e8c0", mons: ["lo_pebblet", "lo_pebblet", "lo_mycora"] },
  glow: { lo: "#163a4a", hi: "#5af0ff", seed: "#c8ffff", mons: ["lo_blinkit", "lo_dreamcap", "lo_mycora"] } };
const tgUnwarp = (x, z) => (TER.ready && TER.low ? unwarp(x, z) : [x, z]);
// a patch centred at authored (cx, cz), radii rx, rz; blades only where the ground is wild (never on paths or water)
const tallGrass = (cx, cz, rx, rz, kind = "meadow", o = {}) => { const [ux, uz] = tgUnwarp(cx, cz), K = TGK[kind] || TGK.meadow, ok = o.any ? null : ".,gx";
  const n = Math.round(rx * rz * Math.PI * (o.dens || 60)); let placed = 0;
  for (let k = 0; k < n; k++) { const a = R() * TAU, r = Math.sqrt(R()), x = ux + Math.cos(a) * r * rx * (0.92 + fbm(a * 3, cx, 2.1) * 0.25), z = uz + Math.sin(a) * r * rz * (0.92 + fbm(a * 3, cz, 4.2) * 0.25);
    if (ok && TER.ready && !ok.includes(atW(x, z))) continue; const edge = 1 - r * r * 0.55; TG.push([x, z, (0.78 + R() * 0.42) * (0.55 + 0.45 * edge) * (o.h || 1), R() * TAU, kind]); placed++; }
  TGP.push({ x: ux, z: uz, rx, rz, kind, mons: o.mons || K.mons, n: placed, name: o.name || "" }); return TGP[TGP.length - 1]; };
const buildTallGrass = () => { if (!TG.length) return; const WF = (H && H.windify) || ((m) => m);
  // a curved, tapering blade with a soft seed head, coloured root-to-tip
  const bg = new THREE.PlaneGeometry(0.13, 1, 1, 6); bg.translate(0, 0.5, 0); { const P = bg.attributes.position, ty = []; for (let i = 0; i < P.count; i++) { const y = P.getY(i); P.setX(i, P.getX(i) * (1 - y * y * 0.85)); P.setZ(i, y * y * 0.38); ty.push(y); } bg.setAttribute("tgy", new THREE.Float32BufferAttribute(ty, 1)); bg.computeVertexNormals(); }
  const mat = WF(std({ side: THREE.DoubleSide, roughness: 0.7 }), 1.25, 1);
  // vertex colour is the height (0..1); the shader mixes the instance's root and tip colours with it
  mat.userData.tg = true; const ob = mat.onBeforeCompile; mat.onBeforeCompile = (sh, r) => { ob && ob(sh, r); sh.vertexShader = "attribute vec3 tgLo; attribute float tgy; varying vec3 vTgLo; varying float vTgY;\n" + sh.vertexShader.replace("#include <begin_vertex>", "#include <begin_vertex>\n vTgLo = tgLo; vTgY = tgy;"); sh.fragmentShader = "varying vec3 vTgLo; varying float vTgY;\n" + sh.fragmentShader.replace("#include <color_fragment>", "#include <color_fragment>\n diffuseColor.rgb = mix(vTgLo, diffuseColor.rgb, smoothstep(0.0, 1.0, vTgY));"); }; const ck = mat.customProgramCacheKey ? mat.customProgramCacheKey.bind(mat) : () => ""; mat.customProgramCacheKey = () => ck() + "tg";
  const IM = new THREE.InstancedMesh(bg, mat, TG.length), lo = new Float32Array(TG.length * 3), m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), v = new THREE.Vector3(), sc = new THREE.Vector3(), cc = new THREE.Color();
  TG.forEach(([x, z, h, r, kind], i) => { const K = TGK[kind] || TGK.meadow; e.set((R() - 0.5) * 0.35, r, (R() - 0.5) * 0.35); q.setFromEuler(e); v.set(x, Math.max(GHT(x, z), 0) - 0.03, z); sc.set(1 + R() * 0.4, h, 1); m4.compose(v, q, sc); IM.setMatrixAt(i, m4); cc.set(K.hi).offsetHSL((R() - 0.5) * 0.04, 0, (R() - 0.5) * 0.1); IM.setColorAt(i, cc); cc.set(K.lo); lo[i * 3] = cc.r; lo[i * 3 + 1] = cc.g; lo[i * 3 + 2] = cc.b; });
  bg.setAttribute("tgLo", new THREE.InstancedBufferAttribute(lo, 3)); IM.castShadow = false; IM.receiveShadow = true; IM.name = "grass"; root.add(IM);
  // glowing seed heads on one blade in nine
  const seeds = TG.filter((_, i) => i % 9 === 0); if (seeds.length) { const sg = new THREE.IcosahedronGeometry(0.035, 0); const SM = new THREE.InstancedMesh(sg, WF(new THREE.MeshBasicMaterial({ color: "#ffffff" }), 1.25, 0), seeds.length); seeds.forEach(([x, z, h, r, kind], i) => { v.set(x + Math.sin(r) * h * 0.36, Math.max(GHT(x, z), 0) + h * 0.98, z + Math.cos(r) * h * 0.36); m4.compose(v, q.identity(), sc.set(1, 1.6, 1)); SM.setMatrixAt(i, m4); cc.set((TGK[kind] || TGK.meadow).seed).multiplyScalar(1.6); SM.setColorAt(i, cc); }); SM.name = "grass"; root.add(SM); } };

// ---- habitat dressing ----
const burrow = (x, z, s = 1) => { const M0 = mk().M; add(olathe([[0.55 * s, 0], [0.62 * s, 0.22 * s], [0.42 * s, 0.34 * s], [0.3 * s, 0.2 * s], [0.001, -0.3]], 18, 0.04, 2), M0.stone, [x, 0, z]); add(new THREE.CircleGeometry(0.3 * s, 14), std({ color: "#0a0806", roughness: 1 }), [x, 0.2 * s, z + 0.05], [-1.2, 0, 0]); for (let k = 0; k < 5; k++) { const a = R() * TAU; add(warp(new THREE.IcosahedronGeometry(0.1 * s, 0), 0.3, 1), M0.stone, [x + Math.cos(a) * 0.8 * s, 0.05, z + Math.sin(a) * 0.8 * s], [R(), R(), R()]); } };
const nest = (x, z, s = 1, egg = "#f0e8ff") => { const M0 = mk().M, G = grp(x, 0, z); for (let k = 0; k < 26; k++) { const a = (k / 26) * TAU + R() * 0.3; limb([[Math.cos(a) * 0.45 * s, 0.05, Math.sin(a) * 0.45 * s], [Math.cos(a + 1.2) * 0.42 * s, 0.22 * s, Math.sin(a + 1.2) * 0.42 * s]], 0.025 * s, 0.02 * s, M0.bark, { seg: 3, rad: 4, knob: 0, parent: G }); } for (let k = 0; k < 3; k++) { const e = add(new THREE.SphereGeometry(0.1 * s, 10, 8), std({ color: egg, emissive: egg, emissiveIntensity: 0.25, roughness: 0.4 }), [(k - 1) * 0.12 * s, 0.12 * s, (k % 2) * 0.08 * s], [0, 0, 0], null, G); e.scale.y = 1.3; } return G; };
const feeder = (x, z, c = "#ffb347") => { const M0 = mk().M, G = grp(x, 0, z, R() * TAU); add(new THREE.CylinderGeometry(0.06, 0.08, 1.1, 6), M0.bark, [0, 0.55, 0], [0, 0, 0], null, G); add(olathe([[0.001, 0], [0.4, 0.02], [0.45, 0.14], [0.001, 0.1]], 16), M0.plank, [0, 1.1, 0], [0, 0, 0], null, G); for (let k = 0; k < 6; k++) add(new THREE.SphereGeometry(0.06, 8, 6), MK.glowC(c, 1.4), [(R() - 0.5) * 0.5, 1.22, (R() - 0.5) * 0.5], [0, 0, 0], null, G); };
const berryBush = (x, z, c = "#ff5ad8") => { const b = add(BUSHG(), mk().M.leaf || mk().M.moss, [x, 0.45, z], [R(), R(), R()]); b.scale.set(0.75, 0.55, 0.75); for (let k = 0; k < 10; k++) { const a = R() * TAU, e = R() * 1.2; add(new THREE.SphereGeometry(0.05, 6, 5), MK.glowC(c, 1.3), [x + Math.cos(a) * Math.cos(e) * 0.7, 0.45 + Math.sin(e) * 0.5, z + Math.sin(a) * Math.cos(e) * 0.7]); } };
const wildSign = (x, z, ry = 0, c = "#c8f06a") => { const G = grp(x, 0, z, ry), M0 = mk().M; add(new THREE.CylinderGeometry(0.06, 0.07, 1.4, 6), M0.bark, [0, 0.7, 0], [0, 0, 0], null, G); const b = add(warp(new THREE.BoxGeometry(0.8, 0.5, 0.06, 2, 2, 1), 0.02, 2), M0.plank, [0, 1.3, 0], [0, 0, 0], null, G); const t = tex(128, 80, (g, W, Hh) => { g.fillStyle = "#6a4a2a"; g.fillRect(0, 0, W, Hh); g.strokeStyle = c; g.lineWidth = 6; g.beginPath(); for (let k = 0; k < 5; k++) { const xx = 22 + k * 21; g.moveTo(xx, 66); g.quadraticCurveTo(xx + 8, 40, xx + 2 + (k % 2) * 8, 14); } g.stroke(); g.fillStyle = c; g.beginPath(); g.arc(98, 22, 9, 0, TAU); g.fill(); }); add(new THREE.PlaneGeometry(0.72, 0.42), std({ map: t, emissive: c, emissiveIntensity: 0.25 }), [0, 1.3, 0.035], [0, 0, 0], null, G); };
// ================= PLACES: pocket scenes, dungeon floors and special interiors (Part 2 pack, sections 6 and 7) =================
// Each place is its own small world far from the region (x >= 400), built on a tile grid of its own.
// Tiles: '#' wall, ' ' void (a drop), '.' floor, ',' stone floor, 'g' glowgrass, 'b' bridge, 'v' violet safe-path moss,
//        'w' water, 'o' solid obstacle, 'S' stairs / hatch / doorway (walkable).
const PLACE = {}; const PLW = (w, d, c = "#") => Array.from({ length: d }, () => Array(w).fill(c));
const pRect = (g, x0, y0, x1, y1, c = ".") => { for (let y = Math.max(0, y0); y <= Math.min(g.length - 1, y1); y++) for (let x = Math.max(0, x0); x <= Math.min(g[0].length - 1, x1); x++) g[y][x] = c; };
const pCirc = (g, cx, cy, r, c = ".", ry = r) => { for (let y = 0; y < g.length; y++) for (let x = 0; x < g[0].length; x++) if (((x + 0.5 - cx) / r) ** 2 + ((y + 0.5 - cy) / ry) ** 2 < 1) g[y][x] = c; };
const pPath = (g, pts, w = 4, c = ".") => { for (let k = 0; k + 1 < pts.length; k++) { const [x0, y0] = pts[k], [x1, y1] = pts[k + 1], n = Math.ceil(Math.hypot(x1 - x0, y1 - y0) * 2); for (let i = 0; i <= n; i++) { const x = x0 + ((x1 - x0) * i) / n, y = y0 + ((y1 - y0) * i) / n; pCirc(g, x, y, w / 2, c); } } };
// wobble the carved edges so caves never look like rooms
const pRough = (g, amt = 0.35, seed = 1) => { const H = g.length, W = g[0].length, o = g.map((r) => r.slice()); for (let y = 1; y < H - 1; y++) for (let x = 1; x < W - 1; x++) { if (o[y][x] !== "#") continue; let n = 0; for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) if (o[y + dy][x + dx] === ".") n++; if (n >= 2 && fbm(x * 0.4 + seed, y * 0.4, seed) > 0.5 - amt) g[y][x] = "."; } };
const PX0 = 400, PZ0 = 400; let PK = 0;
const defPlace = (id, o) => { o.id = id; o.ox = PX0 + PK * 80; o.oz = PZ0; PK++; PLACE[id] = o; };

// ---------- the twelve places ----------
defPlace("canopy", { name: "Canopy Walkways", w: 30, d: 30, style: "canopy", indoor: false, grid() { const g = PLW(30, 30, " "); const C = [[15, 24, 4.3], [7, 16, 3.8], [15, 15, 4.2], [23, 16, 3.8], [8, 6, 3.6], [22, 6, 4.0]]; this.caps = C; for (const [x, y, r] of C) pCirc(g, x, y, r, "."); for (const [a, b] of [[0, 2], [1, 2], [2, 3], [1, 4], [3, 5], [2, 5]]) { const [x0, y0] = C[a], [x1, y1] = C[b]; pPath(g, [[x0, y0], [x1, y1]], 3, "b"); } for (const [x, y, r] of C) pCirc(g, x, y, r, "."); pCirc(g, 7, 16, 2.4, "g"); pCirc(g, 23, 16, 2.2, "g"); pRect(g, 14, 28, 15, 28, "S"); pRect(g, 14, 27, 15, 27, "."); return g; },
  arrive: { in: [15, 26.5, 0] }, portals: [{ t: [15, 28.5], to: "out:A5", label: "Climb down the Spiral Stalk" }] });
