MF.bridges = [];
for (const X of [30, 60]) { const Y = 30, hub = MF.caps.find((c) => c.hub && c.x === X + 15);
  for (const [dx, dz] of [[-1, -1], [1, -1], [-1, 1], [1, 1]]) { const cap = MF.caps.find((c) => !c.hub && Math.sign(c.x - hub.x) === dx && Math.sign(c.z - hub.z) === dz && Math.abs(c.x - hub.x) < 12);
    const k = 0.7071, ra = hub.hx - 0.5, rb = 6.05 * Math.pow(2, -1 / 6) - 0.9; MF.bridges.push({ ax: hub.x + dx * ra * k, az: hub.z + dz * ra * k, ha: hub.h, bx: cap.x - dx * rb, bz: cap.z - dz * rb, hb: cap.h, w: 1.25, sag: 0.25 }); } }
{ const a = MF.caps.find((c) => c.hub && c.x === 45), b = MF.caps.find((c) => c.hub && c.x === 75); MF.bridges.push({ ax: a.x + a.hx - 0.5, az: 46.3, ha: a.h, bx: b.x - b.hx + 0.5, bz: 46.3, hb: b.h, w: 1.35, sag: 0.9, long: 1 });
  // short plank walks from the B3 doors that face the street down onto the long bridge
  for (const dx of [63, 81, 87]) if (dx < b.x - b.hx) MF.bridges.push({ ax: dx, az: 42.6, ha: MF.H, bx: dx, bz: 46.0, hb: MF.H, w: 1.0, sag: 0.05, branch: 1 }); }
