  for (let k = 0; k < 420; k++) { const x = R() * W, y = h2 + R() * h2 * 0.8, s = 4 + R() * 9; g.fillStyle = hsl(28 + R() * 10, 35, 46 + R() * 14, 0.85); g.beginPath(); g.moveTo(x - s, y + s * 0.4); g.quadraticCurveTo(x, y - s, x + s, y + s * 0.4); g.quadraticCurveTo(x, y + s * 0.1, x - s, y + s * 0.4); g.fill(); g.fillStyle = "rgba(255,250,235,0.5)"; g.fillRect(x - s * 0.4, y - s * 0.3, s * 0.6, 2); }
