  door: std({ map: boards(256, 512, 4, true, 22, 30) }), rock: std({ map: rep(tex(512, 512, (g, W) => { g.fillStyle = "#4a463e"; g.fillRect(0, 0, W, W); for (let k = 0; k < 900; k++) { g.fillStyle = hsl(30 + R() * 40, 10, 22 + R() * 26, 0.6); g.beginPath(); g.ellipse(R() * W, R() * W, 6 + R() * 20, 3 + R() * 10, R() * 3, 0, TAU); g.fill(); } moss(g, W, 0, W, 500, 0.55); hp(g, W, W, false); }), 2, 1), roughness: 1 }),
