// weld shading across separate meshes that share edges (e.g. stacked wall bands): average normals at shared positions
const weld = (meshes) => { const map = new Map(); for (const m of meshes) { const P = m.geometry.attributes.position, N = m.geometry.attributes.normal; for (let i = 0; i < P.count; i++) { const k = `${P.getX(i).toFixed(3)},${P.getY(i).toFixed(3)},${P.getZ(i).toFixed(3)}`; (map.get(k) || map.set(k, []).get(k)).push([N, i]); } }
  for (const L of map.values()) if (L.length > 1) { let x = 0, y = 0, z = 0; for (const [N, i] of L) { x += N.getX(i); y += N.getY(i); z += N.getZ(i); } const l = Math.hypot(x, y, z) || 1; for (const [N, i] of L) N.setXYZ(i, x / l, y / l, z / l); } for (const m of meshes) m.geometry.attributes.normal.needsUpdate = true; };
