// which named walk-in gets which room
const DROOM = { "Your House": "yourHouse", "Crater Observatory": "vashtiLab", "Dustmere Recovery Bay": "recoveryBay", "Trading Post Recovery Bay": "recoveryBay", "Port Ember Recovery Bay": "recoveryBay",
  "Dustmere Shop": "dShop", "Harbor Store": "dShop", "Lantern Shop": "dShop", "Reyes House": "reyes", "Cactus Tea House": "teaHouse", "Rock Collector's Den": "rockDen", "Rune Workshop": "runeWorkshop", "Palm Isle Recovery Hut": "palmHut",
  "Abernathy's Bakery": "bakery", "The Trading Post": "tradingHall", "Wayfarers' Inn": "inn", "Ember Inn": "inn", "Climbers' Bunkhouse": "inn", "Watchtower": "watchtower",
  "Harbor Master's House": "frontierHome", "Islander's Stilt Hut": "frontierHome", "Miners' Bunkhouse": "frontierHome",
  "Green Home": "cottage", "Lane Home": "cottage", "Rim Home": "cottage", "Quiet Court Home": "cottage", "Gardener's Home": "cottage", "Old Resident's Home": "cottage", "Dusty's Homestead": "cottage", "Farm Kid's Family Home": "cottage", "Scholar's Cottage": "cottage", "Hermit's Hut": "frontierHome",
  "Sandglass Recovery Hut": "recoveryBay", "Sandglass Supply": "dShop", "Hamlet Home": "cottage", "Caravan Bunkhouse": "inn", "Caravan Trader": "dShop", "Rust Creek Farmhouse": "cottage", "Creek Home": "cottage", "Gulch Waystation": "cottage" };
const dRoomFor = (o) => { const r = o && DROOM[o.name]; if (!r) return null; const [k, opt] = Array.isArray(r) ? r : [r, {}]; return (cx, cz, rx, rz, fh) => DFURN[k](cx, cz, rx, rz, fh, opt); };
// ================= DUSTARA KIT, PART 2: the canyon wilds =================
// natural rock arch (scenery: always over solid ground, never over a path)
D.arch = (x, z, span = 6, h = 5, ry = 0, th = 1.4) => { const G = grp(x, 0, z, ry), pts = []; for (let k = 0; k <= 16; k++) { const t = k / 16, a = Math.PI * t; pts.push([-Math.cos(a) * span / 2, Math.sin(a) * h, 0]); } limb(pts.map(([a, b, c]) => [a, b, c]), th, th * 0.75, D.rock(), { seg: 40, rad: 10, knob: 0.4, parent: G }); for (const s of [-1, 1]) add(warp(new THREE.CylinderGeometry(th * 1.1, th * 1.5, 1.6, 9, 2), 0.2, 0.8), D.rock(), [s * span / 2, 0.6, 0], [0, 0, 0], null, G); return G; };
// palm tree (date palm with fruit, or a coconut-less oasis palm)
D.palm = (x, z, h = 4.2, lean = 0.2) => { const T = grp(x, 0, z, R() * TAU); limb([[0, 0, 0], [lean * 0.5, h * 0.5, 0.05], [lean, h, 0]], 0.17, 0.12, D.palmBark(), { seg: 10, rad: 6, parent: T }); for (let k = 0; k < 9; k++) { const a = (k / 9) * TAU + R() * 0.3, L = 1.6 + R() * 0.6, pts = []; for (let t = 0; t <= 1.001; t += 0.25) pts.push([lean + Math.cos(a) * L * t, h + Math.sin(t * Math.PI * 0.8) * 0.5 - t * t * 1.0, Math.sin(a) * L * t]); limb(pts, 0.07, 0.02, D.frond(), { seg: 8, rad: 3, parent: T }); } for (let k = 0; k < 5; k++) add(new THREE.SphereGeometry(0.1, 6, 5), std({ color: "#a8582a" }), [lean + (R() - 0.5) * 0.4, h - 0.3, (R() - 0.5) * 0.4], [0, 0, 0], null, T); return T; };
D.palmBark = () => D._pb || (D._pb = std({ map: MK.barkT, color: "#d8b080", roughness: 0.9 }));
D.frond = () => D._fr || (D._fr = std({ color: "#5aa03a", roughness: 0.7 }));
// a whole scene of water at the shoreline height: shows only where the ground dips into a basin (w tiles)
D.water = (X, Y, c = "#2fb0b8", e = "#0a5056") => { const w = add(new THREE.PlaneGeometry(36, 36), std({ color: c, roughness: 0.06, metalness: 0.3, emissive: e, emissiveIntensity: 0.55, transparent: true, opacity: 0.86 }), [X + 15, WATER_Y, Y + 15], [-Math.PI / 2, 0, 0]); w.name = "water"; w.userData.noLift = true; return w; };
// one-way ledge drawn as a low banded rock ridge with a light lip on its downhill (south) side
D.ledge = (x0, z, x1) => { const L = x1 - x0; add(warp(soft(new THREE.BoxGeometry(L, 0.75, 0.7, Math.max(2, Math.round(L)), 1, 1), { bulge: 0.04 }), 0.08, 1.2), D.rock(), [(x0 + x1) / 2, 0.3, z]); add(warp(new THREE.BoxGeometry(L + 0.1, 0.12, 0.25, Math.max(2, Math.round(L)), 1, 1), 0.04, 1.4), D.paleStone(), [(x0 + x1) / 2, 0.68, z + 0.3]); };
// standing waystone with a turquoise rune band
D.waystone = (x, z, h = 2.4) => { const G = grp(x, 0, z, R() * TAU); add(warp(soft(new THREE.BoxGeometry(0.7, h, 0.55, 2, 5, 2), { taper: 0.25, warp: 0.06 }), 0.04, 1.4), D.sandstone(), [0, h / 2, 0], [0, 0, 0], null, G); add(new THREE.BoxGeometry(0.66, 0.12, 0.52), MK.glowC("#7ff0e6", 1.2), [0, h * 0.62, 0], [0, 0, 0], null, G); return G; };
// canvas tent with striped flaps (closed, scenery)
D.tent = (x, z, ry = 0, c = "#c84a2a") => { const G = grp(x, 0, z, ry), sh = new THREE.Shape([new THREE.Vector2(-1.3, 0), new THREE.Vector2(1.3, 0), new THREE.Vector2(0, 1.9)]); const pr = new THREE.ExtrudeGeometry(sh, { depth: 2.6, bevelEnabled: false }); pr.translate(0, 0, -1.3); add(pr, D.cloth("#efe2c4"), [0, 0, 0], [0, 0, 0], null, G); for (const s of [-1, 1]) add(new THREE.ShapeGeometry(sh), D.awningM(c, "#efe2c4"), [0, 0, s * 1.32], [0, 0, 0], null, G); for (const s of [-1, 1]) add(new THREE.CylinderGeometry(0.03, 0.03, 2.2, 4), D.wood(), [0, 1.0, s * 1.38], [0, 0, 0], null, G); return G; };
// a huge curled golden Starfall seedpod shell, half buried
D.seedpod = (x, z, s = 1, ry = 0) => { const G = grp(x, -0.6 * s, z, ry); const g = olathe([[0.001, 0], [1.2, 0.3], [1.9, 1.2], [2.0, 2.4], [1.6, 3.4], [0.9, 4.0], [0.001, 4.2]], 28, 0.08, 1.2); const P = g.attributes.position; for (let i = 0; i < P.count; i++) { const y = P.getY(i); P.setX(i, P.getX(i) + Math.sin(y * 0.7) * 0.6); } g.computeVertexNormals(); const m = add(g, D.podM(), [0, 0, 0], [Math.PI / 2 - 0.4, 0, 0], null, G); m.scale.setScalar(s * 1.4); for (let k = 0; k < 6; k++) { const sh = add(D.geo().shard, D.glass(), [(R() - 0.5) * 2 * s, (0.6 + R()) * s, (R() - 0.5) * 3 * s], [R(), R(), R()], null, G); sh.scale.set(0.08 * s, 0.4 * s, 0.08 * s); } return G; };
D.podM = () => D._pod || (D._pod = std({ color: "#e8c060", roughness: 0.35, metalness: 0.25, emissive: "#5a3a08", emissiveIntensity: 0.3, side: THREE.DoubleSide }));
// bleached skeleton of a huge ancient desert beast (old, harmless scenery)
D.skeleton = (x, z, ry = 0, s = 1) => { const G = grp(x, 0, z, ry), B = D.boneM(); limb([[-4 * s, 0.4, 0], [-1 * s, 0.9 * s, 0.1], [2 * s, 0.8 * s, 0], [4.2 * s, 0.4, 0]], 0.22 * s, 0.12 * s, B, { seg: 20, rad: 6, parent: G }); for (let k = 0; k < 7; k++) { const px = (-2.4 + k * 0.7) * s; for (const sd of [-1, 1]) limb([[px, 0.85 * s, 0], [px + 0.1, 1.4 * s, sd * 0.9 * s], [px + 0.2, 0.2, sd * 1.4 * s]], 0.07 * s, 0.04 * s, B, { seg: 8, rad: 4, parent: G }); } const sk = add(new THREE.SphereGeometry(0.7 * s, 12, 8), B, [4.8 * s, 0.5, 0], [0, 0, 0], null, G); sk.scale.set(1.5, 0.8, 0.9); for (const sd of [-1, 1]) limb([[4.9 * s, 0.9 * s, sd * 0.4 * s], [5.8 * s, 1.6 * s, sd * 1.0 * s], [6.4 * s, 1.5 * s, sd * 0.6 * s]], 0.1 * s, 0.03 * s, B, { seg: 8, rad: 5, parent: G }); return G; };
D.boneM = () => D._bone || (D._bone = std({ color: "#f4ecd8", roughness: 0.7 }));
// caravan wagon (no animals): canvas hood on hoops, big spoked wheels
D.wagon = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); add(warp(new THREE.BoxGeometry(1.6, 0.5, 3.0, 2, 1, 3), 0.02, 2), D.wood(), [0, 0.95, 0], [0, 0, 0], null, G); const hood = add(new THREE.CylinderGeometry(0.85, 0.85, 2.8, 14, 1, true, -Math.PI / 2, Math.PI), D.cloth("#efe2c4"), [0, 1.25, 0], [Math.PI / 2, 0, 0], null, G); for (const s of [-1, 1]) for (const zz of [-1.0, 1.0]) { add(new THREE.TorusGeometry(0.5, 0.06, 6, 16), D.wood(), [s * 0.85, 0.52, zz], [0, Math.PI / 2, 0], null, G); for (let k = 0; k < 4; k++) add(new THREE.CylinderGeometry(0.025, 0.025, 1.0, 4), D.wood(), [s * 0.85, 0.52, zz], [k * 0.78, 0, 0], null, G); } return G; };
// a tall wooden signpost with icon arrow boards (no letters)
