// ================= WILDLIFE: tall-grass encounter patches, nests, burrows and feeding spots =================
// tallGrass() lays a patch of tall swaying blades and records it as an encounter zone; the game spawns wild
// Alienmon that roam inside the patch and can pop out of the grass when Rook walks through.
const TG = [], TGP = [];
const TGK = { // blade colours (root -> tip), seed-head glow, and who lives there
  meadow: { lo: "#1e5a2a", hi: "#b8f07a", seed: "#e8ff9a", mons: ["lo_sporix", "lo_chirpod", "lo_blinkit"] },
  fen: { lo: "#1a4a4a", hi: "#7ae0c8", seed: "#9af0ff", mons: ["lo_gloopa", "lo_mycora", "lo_gloopa"] },
  spore: { lo: "#4a2a5a", hi: "#ff9ad8", seed: "#ffd0f0", mons: ["lo_dreamcap", "lo_blinkit", "lo_sporix"] },
  ember: { lo: "#5a3a1a", hi: "#ffc860", seed: "#fff0a0", mons: ["lo_chirpod", "lo_pebblet", "lo_sporix"] },
  rocky: { lo: "#3a4a3a", hi: "#a8c890", seed: "#d8e8c0", mons: ["lo_pebblet", "lo_pebblet", "lo_mycora"] },
  glow: { lo: "#163a4a", hi: "#5af0ff", seed: "#c8ffff", mons: ["lo_blinkit", "lo_dreamcap", "lo_mycora"] },
  // Dustara: knee-high dry golden drift grass with tiny blue sparks at the tips
  // Dustara caves: rusty rubble tufts with turquoise tips (Sunset Tunnel B1, Red Rock Caves B1/B2: encounters 012, 442, 443), dark basalt tufts with violet tips (Tunnel B2, Depths: 013, 444)
  cave: { lo: "#4a2a1a", hi: "#a8643a", seed: "#7ff0e6", mons: ["lo_pebblet", "lo_chirpod", "lo_shadebit", "lo_liftant", "lo_dunetrot", "lo_magnub", "lo_bouldron"] },
  cavedeep: { lo: "#1e1a22", hi: "#5a4a6a", seed: "#c86aff", mons: ["lo_squawktone", "lo_umbrask", "lo_blinkit", "lo_liftant", "lo_dunetrot", "lo_pebblet"] },
  geode: { lo: "#2a1030", hi: "#a84ae8", seed: "#ff7ab0", mons: ["lo_squawktone", "lo_umbrask", "lo_blinkit", "lo_liftant", "lo_dunetrot", "lo_pebblet"] },
  // Molten Frontier: grey ash grass with ember-orange tips; tall green beach grass with red flowers (species per scene come from the encounter tables, passed as mons)
  ash: { lo: "#4a4644", hi: "#a8a29a", seed: "#ff8a2a", mons: ["lo_ashpup", "lo_charsprout", "lo_cindermole", "lo_dunetrot", "lo_liftant"] },
  beach: { lo: "#2a6a2a", hi: "#7ac860", seed: "#e0303a", mons: ["lo_bogeel", "lo_drippit", "lo_blinkit", "lo_spinelord", "lo_dunetrot"] },
  drift: { lo: "#6a4a1e", hi: "#d8b462", seed: "#8ad8ff", mons: ["lo_dunetrot", "lo_pebblet", "lo_skitterbit", "lo_tiktrill", "lo_spindyn"] },
  farm: { lo: "#5a4a1a", hi: "#ccb050", seed: "#8ad8ff", mons: ["lo_hivemaw", "lo_tiktrill", "lo_skitterbit", "lo_dunetrot"] },
  oasis: { lo: "#4a5a22", hi: "#c8c070", seed: "#8ad8ff", mons: ["lo_dunetrot", "lo_fizzle", "lo_fizzlord", "lo_bogeel", "lo_drippit", "lo_liftant"] },
  mesa: { lo: "#6a3e1a", hi: "#d8a858", seed: "#a8e0ff", mons: ["lo_pebblet", "lo_dunetrot", "lo_liftant", "lo_spindyn"] } };
const tgUnwarp = (x, z) => (TER.ready && TER.low ? unwarp(x, z) : [x, z]);
// a patch centred at authored (cx, cz), radii rx, rz; blades only where the ground is wild (never on paths or water)
const tallGrass = (cx, cz, rx, rz, kind = "meadow", o = {}) => { const [ux, uz] = tgUnwarp(cx, cz), K = TGK[kind] || TGK.meadow, ok = o.any ? null : ".,gx";
  const n = Math.round(rx * rz * Math.PI * (o.dens || 60)); let placed = 0;
  for (let k = 0; k < n; k++) { const a = R() * TAU, r = Math.sqrt(R()), x = ux + Math.cos(a) * r * rx * (0.92 + fbm(a * 3, cx, 2.1) * 0.25), z = uz + Math.sin(a) * r * rz * (0.92 + fbm(a * 3, cz, 4.2) * 0.25);
    if (ok && TER.ready && !ok.includes(atW(x, z))) continue; const edge = 1 - r * r * 0.55; TG.push([x, z, (0.78 + R() * 0.42) * (0.55 + 0.45 * edge) * (o.h || 1), R() * TAU, kind]); placed++; }
  TGP.push({ x: ux, z: uz, rx, rz, kind, mons: o.mons || K.mons, n: placed, name: o.name || "" }); return TGP[TGP.length - 1]; };
const buildTallGrass = () => { if (!TG.length) return; const WF = (H && H.windify) || ((m) => m);
  // a curved, tapering blade with a soft seed head, coloured root-to-tip
  const bg = new THREE.PlaneGeometry(0.13, 1, 1, 6); bg.translate(0, 0.5, 0); { const P = bg.attributes.position, ty = []; for (let i = 0; i < P.count; i++) { const y = P.getY(i); P.setX(i, P.getX(i) * (1 - y * y * 0.85)); P.setZ(i, y * y * 0.38); ty.push(y); } bg.setAttribute("tgy", new THREE.Float32BufferAttribute(ty, 1)); bg.computeVertexNormals(); }
  const mat = WF(std({ side: THREE.DoubleSide, roughness: 0.7 }), 1.25, 1);
  // vertex colour is the height (0..1); the shader mixes the instance's root and tip colours with it
  mat.userData.tg = true; const ob = mat.onBeforeCompile; mat.onBeforeCompile = (sh, r) => { ob && ob(sh, r); sh.vertexShader = "attribute vec3 tgLo; attribute float tgy; varying vec3 vTgLo; varying float vTgY;\n" + sh.vertexShader.replace("#include <begin_vertex>", "#include <begin_vertex>\n vTgLo = tgLo; vTgY = tgy;"); sh.fragmentShader = "varying vec3 vTgLo; varying float vTgY;\n" + sh.fragmentShader.replace("#include <color_fragment>", "#include <color_fragment>\n diffuseColor.rgb = mix(vTgLo, diffuseColor.rgb, smoothstep(0.0, 1.0, vTgY));"); }; const ck = mat.customProgramCacheKey ? mat.customProgramCacheKey.bind(mat) : () => ""; mat.customProgramCacheKey = () => ck() + "tg";
  const IM = new THREE.InstancedMesh(bg, mat, TG.length), lo = new Float32Array(TG.length * 3), m4 = new THREE.Matrix4(), q = new THREE.Quaternion(), e = new THREE.Euler(), v = new THREE.Vector3(), sc = new THREE.Vector3(), cc = new THREE.Color();
  TG.forEach(([x, z, h, r, kind], i) => { const K = TGK[kind] || TGK.meadow; e.set((R() - 0.5) * 0.35, r, (R() - 0.5) * 0.35); q.setFromEuler(e); v.set(x, Math.max(GHT(x, z), 0) - 0.03, z); sc.set(1 + R() * 0.4, h, 1); m4.compose(v, q, sc); IM.setMatrixAt(i, m4); cc.set(K.hi).offsetHSL((R() - 0.5) * 0.04, 0, (R() - 0.5) * 0.1); IM.setColorAt(i, cc); cc.set(K.lo); lo[i * 3] = cc.r; lo[i * 3 + 1] = cc.g; lo[i * 3 + 2] = cc.b; });
  bg.setAttribute("tgLo", new THREE.InstancedBufferAttribute(lo, 3)); IM.castShadow = false; IM.receiveShadow = true; IM.name = "grass"; root.add(IM);
  // glowing seed heads on one blade in nine
  const seeds = TG.filter((_, i) => i % 9 === 0); if (seeds.length) { const sg = new THREE.IcosahedronGeometry(0.035, 0); const SM = new THREE.InstancedMesh(sg, WF(new THREE.MeshBasicMaterial({ color: "#ffffff" }), 1.25, 0), seeds.length); seeds.forEach(([x, z, h, r, kind], i) => { v.set(x + Math.sin(r) * h * 0.36, Math.max(GHT(x, z), 0) + h * 0.98, z + Math.cos(r) * h * 0.36); m4.compose(v, q.identity(), sc.set(1, 1.6, 1)); SM.setMatrixAt(i, m4); cc.set((TGK[kind] || TGK.meadow).seed).multiplyScalar(1.6); SM.setColorAt(i, cc); }); SM.name = "grass"; root.add(SM); } };

