    for (let k = 0; k < 7; k++) { const x = 15 + R() * 10, y = 11.5 + R() * 7; if (Math.abs(y - 15) < 1.8) continue; const d = add(new THREE.CylinderGeometry(0.02, 0.02, 4.5, 4), std({ color: "#9af0ff", emissive: "#5af0e0", emissiveIntensity: 1, transparent: true, opacity: 0.5 }), [X(x), 3.2, Z(y)]); d.name = "nocol"; } // drips from the sea above
