// ================= THE CANYON STEPS (Book 1: "112 stone steps"; Dustmere is a canyon town where three canyons meet) =================
// 112 carved sandstone steps leave the west rim beside the humming bridge, cling to the canyon wall, then run east along the bend
// down to a little camp on the canyon floor (16 m below). A swaying rope bridge crosses the east canyon from the Trading Post rim
// to the Oasis Fork, right over the camp. Walking works through the terrain: the step and floor tiles get a height ramp (D.elev).
const CSTEP = { pts: [[66.95, 49.6], [66.95, 55.95], [93.4, 55.95]], w: 2, n: 112 };
CSTEP.seg = []; { let s = 0; for (let i = 0; i + 1 < CSTEP.pts.length; i++) { const [a, b] = [CSTEP.pts[i], CSTEP.pts[i + 1]], L = Math.hypot(b[0] - a[0], b[1] - a[1]); CSTEP.seg.push({ a, b, L, s0: s }); s += L; } CSTEP.L = s; }
const CFLOOR = [93, 55, 99, 66], CBRIDGE = [100, 55, 102, 68];
const cIsStep = (x, y) => (x >= 66 && x <= 67 && y >= 50 && y <= 56) || (y >= 55 && y <= 56 && x >= 66 && x <= 92);
const cIsFloor = (x, y) => x >= CFLOOR[0] && x <= CFLOOR[2] && y >= CFLOOR[1] && y <= CFLOOR[3];
// distance along the stair centre line for a tile-space point (projects onto the nearest segment)
const cAlong = (a, b) => { let best = 1e9, sb = 0; for (const g of CSTEP.seg) { const dx = g.b[0] - g.a[0], dz = g.b[1] - g.a[1], t = Math.max(0, Math.min(1, ((a - g.a[0]) * dx + (b - g.a[1]) * dz) / (g.L * g.L))), px = g.a[0] + dx * t, pz = g.a[1] + dz * t, d = Math.hypot(a - px, b - pz); if (d < best) { best = d; sb = g.s0 + g.L * t; } } return sb; };
D.lowWalk = (ci, cj) => cIsStep(ci, cj) || cIsFloor(ci, cj);
{ const e0 = D.elev; D.elev = (x, z) => { const base = e0 ? e0(x, z) : 0; if (!TER.ready) return base; const [a, b] = warpXY(x, z), ci = Math.floor(a), cj = Math.floor(b);
    if (cIsFloor(ci, cj)) return base + CANYON_Y + 0.2; if (cIsStep(ci, cj)) return base + (CANYON_Y + 0.2) * Math.min(1, Math.max(0, cAlong(a, b) / CSTEP.L)); return base; }; }
const cGround = (sid, fn) => { const g0 = SCN[sid].ground; SCN[sid].ground = function () { g0.call(this); fn(); }; };
const cBuild = (sid, fn) => { const b0 = SCN[sid].build; SCN[sid].build = function () { b0.call(this); fn(); }; };
