  const at = (s) => { for (const g of CSTEP.seg) if (s <= g.s0 + g.L + 1e-6) { const t = (s - g.s0) / g.L; return [g.a[0] + (g.b[0] - g.a[0]) * t, g.a[1] + (g.b[1] - g.a[1]) * t, Math.atan2(g.b[0] - g.a[0], g.b[1] - g.a[1])]; } const g = CSTEP.seg[CSTEP.seg.length - 1]; return [g.b[0], g.b[1], Math.atan2(g.b[0] - g.a[0], g.b[1] - g.a[1])]; };
