// ================= OBSERVATORY HILL (OBSHILL; Book 1: "The Observatory sat at the very top of the town, on the highest point of the canyon rim ... you had to climb one hundred and twelve stone steps") =================
// The observatory grounds in DB1 sit on a sandstone mesa OBS_H m above the town. 112 carved steps climb its east flank from the south end of the
// Observatory Road (tile cols 12-13, rows 58.6 up to 46) to a landing that joins the hilltop. Walking works through D.elev, like the canyon steps.
const OBS_H = 8.0, OBS_C = [7.6, 39.4], OBS_R = [6.9, 6.4], OSTEP = { x0: 12.0, x1: 14.0, b0: 58.6, b1: 46.0, n: 112 };
const oHillQ = (a, b) => Math.hypot((a - OBS_C[0]) / OBS_R[0], (b - OBS_C[1]) / OBS_R[1]);
const oIsStep = (a, b) => a >= OSTEP.x0 && a < OSTEP.x1 && b >= OSTEP.b1 && b <= OSTEP.b0;
const oIsLand = (a, b) => a >= 10.6 && a < OSTEP.x1 && b >= 43.6 && b < OSTEP.b1 + 0.05;
{ const e0 = D.elev; D.elev = (x, z) => { const base = e0 ? e0(x, z) : 0; if (!TER.ready) return base; const [a, b] = warpXY(x, z);
    if (oIsStep(a, b)) return base + OBS_H * Math.min(1, Math.max(0, (OSTEP.b0 - b) / (OSTEP.b0 - OSTEP.b1)));
    if (oIsLand(a, b)) return base + OBS_H; const q = oHillQ(a, b); if (q < 1) return base + OBS_H; if (q < 1.1) return base + OBS_H * (1 - sstep(1, 1.1, q)); return base; }; }
