  if (PEB.length) { const g = warp(new THREE.IcosahedronGeometry(1, 0), 0.18, 1.2); smoothSeams(g); const IM = new THREE.InstancedMesh(g, std({ color: "#ffffff", roughness: 0.9 }), PEB.length); PEB.forEach(([x, z, s], i) => { e.set(R() * 3, R() * 3, R() * 3); q.setFromEuler(e); v.set(x, GHT(x, z) + s * 0.25, z); sc.set(s * (0.8 + R() * 0.6), s * 0.55, s * (0.8 + R() * 0.6)); m4.compose(v, q, sc); IM.setMatrixAt(i, m4); cc.setHSL(0.1 + R() * 0.5, 0.08 + R() * 0.12, 0.45 + R() * 0.3); IM.setColorAt(i, cc); }); IM.name = "grass"; IM.receiveShadow = true; IM.castShadow = false; root.add(IM); }
