  // ---- Wayfarers' Inn (and the other inns): a front desk, a hearth, round tables, a staircase up one side, rugs, a blank notice board ----
  inn: (cx, cz, rx, rz, fh) => { counter(cx, cz - rz * 0.5, rx * 0.7, 0.55, { c: "#7a3ab0", items: "lanterns", step: 0.6 }); FUR.hearth(root, cx - rx * 0.6, dIn.Y, cz - rz * 0.6, 0.5); dStairs(cx + rx * 0.72, cz + rz * 0.2, 0, 6, 0.75);
    for (const [x, z] of [[-0.45, 0.15], [0.15, 0.4]]) { FUR.table(root, cx + rx * x, dIn.Y, cz + rz * z, 0.42); FUR.stool(root, cx + rx * x + 0.6, dIn.Y, cz + rz * z); FUR.stool(root, cx + rx * x - 0.6, dIn.Y, cz + rz * z); }
    add(new THREE.BoxGeometry(0.9, 0.6, 0.04), D.wood(), [cx + rx * 0.3, 1.6, cz - rz * 0.97]); rugR(cx, cz + rz * 0.62, 0.6, 0.35, "#7a3ab0", "#2a9a96").position.y = 0.09; hangLamp(cx, cz, "#ffc070", fh - 0.5); },

