// wild scatter: saguaros, prickly pears, agaves and crater-glass on sand tiles well away from paths and buildings
const dWild = (X, Y, n = 10, o = {}) => { let k = 0, tries = 0; while (k < n && tries++ < n * 30) { const x = X + 1 + R() * 28, z = Y + 1 + R() * 28; if (at(Math.floor(x), Math.floor(z)) !== "." || distW(x, z) < (o.d || 2.5)) continue; k++; const q = R(); if (q < 0.3) D.saguaro(x, z, 1.8 + R() * 2.6); else if (q < 0.55) D.prickly(x, z, 0.7 + R() * 0.6); else if (q < 0.75) D.agavePlant(x, z, 0.8 + R() * 0.5); else if (q < 0.88) boulder(x, 0, z, 0.4 + R() * 0.7, D.rock(), 0.6); else D.craterRock(x, z, 0.35 + R() * 0.3); } };
const dLamps = (X, Y, pts) => { for (const [x, z] of pts) sporeLantern(X + x, Y + z); };
const dSlab = (x, z, ry = 0) => { const s = add(warp(new THREE.BoxGeometry(0.9, 0.08, 0.7, 2, 1, 2), 0.02, 2), D.paleStone(), [x, 0.05, z], [0, ry, 0]); s.name = "stash"; return s; };
const dDrifts = (X, Y, pts) => { for (const [x, z] of pts) { const b = add(new THREE.SphereGeometry(1, 10, 6, 0, TAU, 0, Math.PI / 2), D.sandM(), [X + x, -0.02, Y + z], [0, R() * 3, 0]); b.scale.set(0.9 + R() * 0.6, 0.18, 0.4 + R() * 0.3); } };
// ================= DUSTARA PLACES: dungeon floors and halls (pack section 14) =================
// Same place system as Sporeholm (places.js): each place is a tile grid built far from the region.
// Tiles: '#' wall, ' ' a drop (chasm), '.' floor, ',' stone floor, 'b' bridge / rock span, 'w' water, 'o' solid obstacle, 'S' stairs / doorway.
// Portal "to" values: "<place>:<arrive key>", or "out:<scene>" for the outdoor door listed in OUTPORTALS.

// ---------- small Dustara dungeon props ----------
const dpRails = (pts, X, Z) => { const ir = D.iron(), wd = D.wood(); for (let k = 0; k + 1 < pts.length; k++) { const [x0, y0] = pts[k], [x1, y1] = pts[k + 1], L = Math.hypot(x1 - x0, y1 - y0), ry = Math.atan2(x1 - x0, y1 - y0), G = grp(X((x0 + x1) / 2), 0, Z((y0 + y1) / 2), ry);
    for (const s of [-0.42, 0.42]) add(new THREE.BoxGeometry(0.07, 0.07, L), ir, [s, 0.06, 0], [0, 0, 0], null, G).name = "nocol";
    for (let t = -L / 2 + 0.3; t < L / 2; t += 0.75) add(new THREE.BoxGeometry(1.15, 0.05, 0.22), wd, [0, 0.025, t], [0, 0, 0], null, G).name = "nocol"; } };
const dpTimber = (x, z, ry = 0, h = 3.4, w = 3.6) => { const G = grp(x, 0, z, ry), wd = D.wood(); for (const s of [-1, 1]) add(warp(new THREE.BoxGeometry(0.28, h, 0.28, 1, 3, 1), 0.03, 2), wd, [s * w / 2, h / 2, 0], [0, 0, s * 0.04], null, G); add(warp(new THREE.BoxGeometry(w + 0.6, 0.3, 0.32, 3, 1, 1), 0.03, 2), wd, [0, h, 0], [0, 0, 0], null, G); return G; };
const dpLantern = (x, z, c = "#ffb060", y = 2.6, i = 2.6, d = 9) => { hangLamp(x, z, c, y); const l = new THREE.PointLight(new THREE.Color(c), i, d, 1.5); l.position.set(x, y - 0.2, z); root.add(l); };
const dpCrystals = (x, z, c, s = 1, n = 5) => { const m = MK.glowC(c, 1.8); for (let k = 0; k < n; k++) { const a = R() * TAU, r = R() * 0.5 * s, h = (0.6 + R() * 1.1) * s; const g = add(new THREE.OctahedronGeometry(0.22 * s, 0), m, [x + Math.cos(a) * r, h * 0.45, z + Math.sin(a) * r], [(R() - 0.5) * 0.7, R() * TAU, (R() - 0.5) * 0.7]); g.scale.y = h / (0.22 * s) * 0.5; } };
const dpCart = (x, z, ry = 0, ore = "#8a4a2a") => { const G = grp(x, 0, z, ry); add(warp(new THREE.BoxGeometry(1.4, 0.7, 1.0, 2, 1, 1), 0.03, 2), D.iron(), [0, 0.65, 0], [0, 0, 0], null, G); for (const s of [-1, 1]) for (const zz of [-0.35, 0.35]) add(new THREE.CylinderGeometry(0.18, 0.18, 0.08, 10), D.iron(), [s * 0.45, 0.2, zz], [0, 0, Math.PI / 2], null, G); for (let k = 0; k < 5; k++) add(new THREE.DodecahedronGeometry(0.2, 0), std({ color: ore, roughness: 0.9 }), [(R() - 0.5) * 0.8, 1.05, (R() - 0.5) * 0.5], [R(), R(), R()], null, G); return G; };
const dpRubble = (x, z, s = 1, n = 6) => { for (let k = 0; k < n; k++) boulder(x + (R() - 0.5) * 1.6 * s, 0.25 * s, z + (R() - 0.5) * 1.6 * s, (0.35 + R() * 0.45) * s, D.rock(), 0.7); };
const dpBlock = (x, z, s = 1.6) => { boulder(x, s * 0.55, z, s, D.rockBig(), 0.8); dpRubble(x, z, 0.8, 4); }; // a boulder that seals a side tunnel
const dpBench = (x, z, ry = 0) => { const G = grp(x, 0, z, ry); add(warp(new THREE.BoxGeometry(1.6, 0.12, 0.45, 2, 1, 1), 0.02, 2), D.wood(), [0, 0.45, 0], [0, 0, 0], null, G); for (const s of [-0.65, 0.65]) add(new THREE.BoxGeometry(0.14, 0.45, 0.4), D.wood(), [s, 0.22, 0], [0, 0, 0], null, G); };
const dpSandbags = (x, z, ry = 0) => { const G = grp(x, 0, z, ry), m = std({ color: "#c8b088", roughness: 1 }); for (let r = 0; r < 3; r++) for (let k = 0; k < 3 - (r === 2 ? 1 : 0); k++) { const b = add(new THREE.CapsuleGeometry(0.22, 0.42, 4, 8), m, [-0.5 + k * 0.5 + (r % 2) * 0.25, 0.2 + r * 0.32, 0], [0, 0, Math.PI / 2], null, G); b.scale.set(1, 1, 0.75); } };
const dpPot = (x, z) => { D.urn(x, z, 1.25); D.prickly(x, z, 0.75); };
const dpStash = (x, z, ry = 0) => { dSlab(x, z, ry); };
const dpRune = (x, z, ry, w = 1.6, y = 2.2, c = "#7ff0e6") => { const m = add(new THREE.BoxGeometry(w, 0.08, 0.04), MK.glowC(c, 1.6), [x, y, z], [0, ry, 0]); m.name = "nocol"; return m; };
const dpShaft = (x, z, c = "#ffb060", h = 6, r = 0.9) => { const m = add(new THREE.ConeGeometry(r, h, 16, 1, true), new THREE.MeshBasicMaterial({ color: c, transparent: true, opacity: 0.12, depthWrite: false, blending: THREE.AdditiveBlending, side: THREE.DoubleSide }), [x, h / 2, z]); m.name = "nocol"; return m; };
const dpPool = (x, z, rx, rz, c = "#2fb0b8") => { const m = add(new THREE.CircleGeometry(1, 32), std({ color: c, roughness: 0.05, metalness: 0.3, emissive: c, emissiveIntensity: 0.45, transparent: true, opacity: 0.85 }), [x, -0.1, z], [-Math.PI / 2, 0, 0]); m.scale.set(rx, rz, 1); m.name = "water"; };

// ---------- Sunset Tunnel ----------
// ================= FERROX KIT (Ferrox pack section 4): rust, riveted steel, corrugated iron, copper pipes, teal coolant, cage lamps =================
// Everything in Rustvale is built from junk: boilers, boxcars, riveted domes with cool blue portholes, corrugated sheds, seedpod-shell roofs.
const XK = {}; const xm = (k, f) => XK[k] || (XK[k] = (mk(), f()));
const XT = {
  rivet: () => xm("tRiv", () => tex(256, 256, (g, W, Hh) => { g.fillStyle = "#5a5450"; g.fillRect(0, 0, W, Hh); for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) { const v = 205 + R() * 40; g.fillStyle = `rgb(${v},${v - 6},${v - 12})`; g.fillRect(x * 64 + 2, y * 64 + 2, 60, 60); }
    for (let k = 0; k < 4; k++) { const x = R() * 200, y = R() * 200, w = 30 + R() * 40; g.fillStyle = `rgba(${R() < 0.5 ? "170,90,50" : "120,130,135"},0.35)`; g.fillRect(x, y, w, w * 0.8); g.strokeStyle = "rgba(40,30,25,0.6)"; g.lineWidth = 2; g.strokeRect(x, y, w, w * 0.8); }
    g.fillStyle = "rgba(50,40,34,0.85)"; for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) for (let q = 0; q < 6; q++) { g.beginPath(); g.arc(x * 64 + 6 + q * 10.4, y * 64 + 6, 2.2, 0, TAU); g.fill(); g.beginPath(); g.arc(x * 64 + 6 + q * 10.4, y * 64 + 58, 2.2, 0, TAU); g.fill(); }
    for (let k = 0; k < 30; k++) { const x = R() * W, y = R() * Hh, L = 20 + R() * 60, gr = g.createLinearGradient(x, y, x, y + L); gr.addColorStop(0, "rgba(150,64,24,0.55)"); gr.addColorStop(1, "rgba(150,64,24,0)"); g.fillStyle = gr; g.fillRect(x, y, 2 + R() * 4, L); } }, [1, 1])),
  corr: () => xm("tCorr", () => tex(256, 256, (g, W, Hh) => { for (let x = 0; x < W; x += 16) { const gr = g.createLinearGradient(x, 0, x + 16, 0); gr.addColorStop(0, "#9a9a9a"); gr.addColorStop(0.5, "#f0f0f0"); gr.addColorStop(1, "#7a7a7a"); g.fillStyle = gr; g.fillRect(x, 0, 16, Hh); }
    for (let k = 0; k < 40; k++) { const x = R() * W, y = R() * Hh, L = 20 + R() * 70, gr = g.createLinearGradient(x, y, x, y + L); gr.addColorStop(0, "rgba(160,70,24,0.6)"); gr.addColorStop(1, "rgba(160,70,24,0)"); g.fillStyle = gr; g.fillRect(x, y, 3 + R() * 6, L); } }, [1, 1])),
  haz: () => xm("tHaz", () => tex(128, 128, (g, W, Hh) => { g.fillStyle = "#1e1612"; g.fillRect(0, 0, W, Hh); g.fillStyle = "#f2c230"; for (let k = -2; k < 4; k++) { g.beginPath(); g.moveTo(k * 64, 0); g.lineTo(k * 64 + 32, 0); g.lineTo(k * 64 + 32 + Hh, Hh); g.lineTo(k * 64 + Hh, Hh); g.closePath(); g.fill(); } }, [1, 1])),
  chain: () => xm("tChain", () => { const t = tex(128, 128, (g, W) => { g.clearRect(0, 0, W, W); g.strokeStyle = "#b8bcc0"; g.lineWidth = 3; for (let k = -8; k < 16; k++) { g.beginPath(); g.moveTo(k * 16, 0); g.lineTo(k * 16 + W, W); g.stroke(); g.beginPath(); g.moveTo(k * 16 + W, 0); g.lineTo(k * 16, W); g.stroke(); } }, [1, 1]); return t; }),
};
const XM = {
  rust: (c = "#b5541c") => xm("rust" + c, () => std({ map: XT.rivet(), color: c, roughness: 0.68, metalness: 0.3 })),
  corr: (c = "#b06030") => xm("corr" + c, () => std({ map: XT.corr(), color: c, roughness: 0.6, metalness: 0.35 })),
  paint: (c) => xm("paint" + c, () => std({ color: c, roughness: 0.6, metalness: 0.2 })),
  steel: () => xm("steel", () => std({ color: "#8f949a", roughness: 0.42, metalness: 0.6 })),
  steelD: () => xm("steelD", () => std({ color: "#5e6266", roughness: 0.5, metalness: 0.55 })),
  iron: () => xm("ironX", () => std({ color: "#3a3532", roughness: 0.6, metalness: 0.45 })),
  dark: () => xm("darkX", () => std({ color: "#2e211a", roughness: 0.9 })),
  copper: () => xm("copX", () => std({ color: "#b87333", roughness: 0.35, metalness: 0.8 })),
  brass: () => xm("brassX", () => std({ color: "#c8943a", roughness: 0.35, metalness: 0.85 })),
  haz: () => xm("hazX", () => std({ map: XT.haz(), roughness: 0.6 })),
  shell: () => xm("shellX", () => std({ color: "#b8ae9e", roughness: 0.5, metalness: 0.05 })),
  tyre: () => xm("tyreX", () => std({ color: "#1c1816", roughness: 0.95 })),
  conc: () => xm("concX", () => std({ map: MK.stoneT || null, color: "#a09486", roughness: 0.95 })),
  wood: () => xm("woodX", () => std({ map: MK.barkT || null, color: "#9a7a5a", roughness: 0.9 })),
  chain: () => xm("chainX", () => std({ map: XT.chain(), color: "#c0c4c8", transparent: true, alphaTest: 0.4, side: THREE.DoubleSide, metalness: 0.6, roughness: 0.4 })),
  lamp: () => MK.glowC("#ffb347", 2.2), port: () => MK.glowC("#6fc3ff", 1.3), cool: () => MK.glowC("#5fe0d0", 1.4), ember: () => MK.glowC("#ff7a1a", 2.4),
};
const XCOL = { rust: "#c8683a", teal: "#4a9a92", mustard: "#c8a040", steel: "#a0a6ac", cream: "#d8d0c0", red: "#a8483a", blue: "#5a7a9a", green: "#6a8a5a" };
const XC = Object.values(XCOL);
// ---- shared geometry ----
const XG = { gear: {}, };
const gearGeo = (teeth = 12, r = 1, hole = 0.35, depth = 0.25) => { const k = teeth + "|" + hole + "|" + depth; if (XG.gear[k]) return XG.gear[k]; const s = new THREE.Shape(), n = teeth * 4; for (let i = 0; i <= n; i++) { const a = (i / n) * TAU, q = i % 4, rr = q === 1 || q === 2 ? r : r * 0.82; i ? s.lineTo(Math.cos(a) * rr, Math.sin(a) * rr) : s.moveTo(Math.cos(a) * rr, Math.sin(a) * rr); }
  if (hole) { const hp2 = new THREE.Path(); hp2.absarc(0, 0, r * hole, 0, TAU, true); s.holes.push(hp2); } const g = new THREE.ExtrudeGeometry(s, { depth, bevelEnabled: true, bevelThickness: depth * 0.12, bevelSize: r * 0.02, bevelSegments: 1, curveSegments: 6 }); g.translate(0, 0, -depth / 2); return (XG.gear[k] = g); };
// a gear standing, leaning or lying flat
const xGear = (x, z, r = 0.8, o = {}) => { const G = grp(x, 0, z, o.ry ?? R() * TAU); const m = add(gearGeo(o.teeth || 10 + Math.floor(R() * 6), 1, 0.3, 0.25), o.mat || (R() < 0.5 ? XM.rust("#a85a30") : XM.steelD()), [0, o.flat ? 0.12 * r : r * 0.95, 0], o.flat ? [-Math.PI / 2, 0, 0] : [o.lean ?? -0.25, 0, 0], null, G); m.scale.setScalar(r); return G; };
// ---- street props ----
let xLamp = (x, z, o = {}) => { const G = grp(x, 0, z, o.ry ?? R() * TAU), h = o.h || 3.3, st = XM.steelD(); add(new THREE.CylinderGeometry(0.07, 0.1, h, 7), st, [0, h / 2, 0], [0, 0, 0], null, G); add(new THREE.CylinderGeometry(0.16, 0.2, 0.25, 8), st, [0, 0.12, 0], [0, 0, 0], null, G);
  limb([[0, h - 0.1, 0], [0.25, h + 0.12, 0], [0.55, h + 0.05, 0]], 0.04, 0.04, st, { seg: 4, rad: 5, parent: G }); add(new THREE.SphereGeometry(0.15, 10, 8), XM.lamp(), [0.55, h - 0.32, 0], [0, 0, 0], null, G);
  for (let k = 0; k < 4; k++) { const a = (k / 4) * TAU + 0.4; add(new THREE.CylinderGeometry(0.012, 0.012, 0.42, 3), st, [0.55 + Math.cos(a) * 0.17, h - 0.32, Math.sin(a) * 0.17], [0, 0, 0], "nocol", G); } add(new THREE.CylinderGeometry(0.2, 0.08, 0.1, 8), st, [0.55, h - 0.1, 0], [0, 0, 0], null, G); add(new THREE.CylinderGeometry(0.06, 0.18, 0.06, 8), st, [0.55, h - 0.54, 0], [0, 0, 0], null, G);
  if (o.light !== false) { const l = new THREE.PointLight(0xffb347, 2.2, 8, 1.6); l.position.set(0.55, h - 0.5, 0); G.add(l); } return G; };
let xDrum = (x, z, c, o = {}) => { const G = grp(x, o.y || 0, z, R() * TAU), m = c === "haz" ? XM.haz() : XM.paint(c || ["#1f8a80", "#a8482a", "#c8a040", "#5a6a7a", "#8a3a2a"][Math.floor(R() * 5)]); add(new THREE.CylinderGeometry(0.3, 0.3, 0.9, 12), m, [0, 0.45, 0], [0, 0, 0], null, G); for (const y of [0.25, 0.65]) add(new THREE.TorusGeometry(0.305, 0.02, 4, 14), XM.iron(), [0, y, 0], [Math.PI / 2, 0, 0], null, G); add(new THREE.CircleGeometry(0.28, 12), XM.iron(), [0, 0.905, 0], [-Math.PI / 2, 0, 0], null, G); if (o.tip) G.rotation.z = Math.PI / 2; return G; };
const xDrums = (x, z, n = 3) => { for (let k = 0; k < n; k++) xDrum(x + (k % 3) * 0.62 - 0.6 + (R() - 0.5) * 0.1, z + Math.floor(k / 3) * 0.62 + (R() - 0.5) * 0.1); if (n >= 3 && R() < 0.6) xDrum(x - 0.3, z + 0.05, null, { y: 0.92 }); };
let xTyres = (x, z, n = 4) => { const G = grp(x, 0, z, R() * TAU); for (let k = 0; k < n; k++) add(new THREE.TorusGeometry(0.4, 0.16, 6, 14), XM.tyre(), [(R() - 0.5) * 0.12, 0.16 + k * 0.3, (R() - 0.5) * 0.12], [Math.PI / 2 + (R() - 0.5) * 0.15, 0, 0], null, G); return G; };
