const fallenCap = (x, z, r = 4, c = "#b06ad8", ry = 0.4) => { const M0 = mk().M, G = grp(x, 0, z, ry); const C = new THREE.Group(); C.position.set(0, r * 0.5, 0); C.rotation.set(0.15, 0, 0.55); G.add(C); add(olathe([[0.001, r * 0.5], [r * 0.5, r * 0.46], [r * 0.85, r * 0.26], [r, 0.02], [r * 0.95, -0.08], [r * 0.3, -0.02], [0.001, 0]], 32, r * 0.04, 1.2), MK.capM(c), [0, 0, 0], [0, 0, 0], null, C); add(new THREE.CircleGeometry(r * 0.93, 32), fbMats().gill, [0, -0.06, 0], [Math.PI / 2, 0, 0], null, C);
  add(olathe([[0.001, 0], [r * 0.24, 0], [r * 0.2, r * 0.5], [r * 0.26, r * 0.55], [0.001, r * 0.5]], 14, 0.05, 2), M0.stalk, [0, -r * 0.5, 0], [0, 0, 0], null, C); limb([[r * 0.9, 0.2, -1.2], [r * 1.4, 0.35, -0.6], [r * 2.0, 0.25, 0.2]], r * 0.2, r * 0.16, M0.stalk, { seg: 10, rad: 10, parent: G }); for (let k = 0; k < 6; k++) bush(x + (R() - 0.5) * r * 1.6, z + (R() - 0.5) * r * 1.4, 0.9); glowcaps(x + r * 0.5, z + r * 0.6, 7, undefined, 1.2); };
const shelfStep = (x, z, r, c = "#e8a050", y = 0, ry = 0) => { const G = grp(x, y, z, ry); const s = add(new THREE.SphereGeometry(1, 20, 8, 0, Math.PI, 0, Math.PI / 2), MK.capM(c), [0, 0, 0], [0, 0, 0], null, G); s.scale.set(r, r * 0.22, r * 0.85); add(new THREE.CircleGeometry(r * 0.98, 20, 0, Math.PI), MK.glowC("#ffd27a", 0.7), [0, -0.01, 0], [Math.PI / 2, 0, 0], null, G).scale.y = 0.85; return G; };
