  add(new THREE.BoxGeometry(2.6, 2.9, 0.5), fr, [0, 1.45, 4.55], [0, 0, 0], null, G); add(new THREE.PlaneGeometry(2.0, 2.4), FXA.haz(), [0, 1.25, 4.81], [0, 0, 0], "nocol", G); add(new THREE.PlaneGeometry(0.06, 2.4), fr, [0, 1.25, 4.83], [0, 0, 0], "nocol", G); fxLantern(0, 3.4, 4.6, 0, G);
