  add(new THREE.BoxGeometry(7.4, 0.2, 7.4), fxM("rivplate", { c: "#b89888", s: 0.8 }), [0, 17.4, 0], [0, 0, 0], null, G); fxRail(G, [[-3.6, -3.6], [3.6, -3.6], [3.6, 3.6], [-3.6, 3.6], [-3.6, -3.6]], 17.5);
