    for (let i = 0; i < p.count; i += 3) { const cy = (p.getY(i) + p.getY(i + 1) + p.getY(i + 2)) / 3; if (cy < -0.08 * r) continue; const q = R(), mi = cy > r * 0.45 && q < 0.22 ? 3 : q < 0.3 ? 0 : q < 0.48 ? 1 : q < 0.72 ? 2 : q < 0.86 ? 4 : 5; for (let j = 0; j < 3; j++) groups[mi].push(p.getX(i + j), Math.max(0, p.getY(i + j)) * 0.85, p.getZ(i + j)); }
