  stone: () => thM("stoneT", () => tex(256, 256, (g, W) => { g.fillStyle = "#8a8478"; g.fillRect(0, 0, W, W); for (let y = 0, r = 0; y < W; y += 36, r++) for (let x = -(r % 2) * 32; x < W; x += 64) { g.fillStyle = `hsl(${35 + R() * 10},${8 + R() * 8}%,${62 + R() * 14}%)`; g.fillRect(x + 2, y + 2, 60, 32); } }, [1, 1])),
