  for (let k = 0; k < 2; k++) add(new THREE.CylinderGeometry(0.5, 0.6, 7, 10), thM("gmast", () => std({ color: "#7a7e82", metalness: 0.5 })), [L * 0.05 + k * 12, 6.5, 0], [0, 0, (R() - 0.5) * 0.1], "nocol", G);
