  const sg = new THREE.PlaneGeometry(SZ * 1.6, SZ * 1.6, 96, 96); sg.rotateX(-Math.PI / 2); const SP = sg.attributes.position, SC2 = []; for (let i = 0; i < SP.count; i++) { const x = SP.getX(i) + cx, z = SP.getZ(i) + cz, d = dist(x, z); const c = new THREE.Color("#3ccac4").lerp(new THREE.Color("#0c5a86"), Math.min(1, d / 26)); SC2.push(c.r, c.g, c.b); }
  sg.setAttribute("color", new THREE.Float32BufferAttribute(SC2, 3)); const idx = sg.index.array, keep = []; for (let i = 0; i < idx.length; i += 3) { let mx = 0, mz = 0; for (let q = 0; q < 3; q++) { mx += SP.getX(idx[i + q]) / 3; mz += SP.getZ(idx[i + q]) / 3; } if (dist(mx + cx, mz + cz) > 0.01) keep.push(idx[i], idx[i + 1], idx[i + 2]); } sg.setIndex(keep);
  const sm = add(sg, new THREE.MeshStandardMaterial({ vertexColors: true, transparent: true, opacity: 0.86, roughness: 0.1, metalness: 0.2, emissive: "#06304a", emissiveIntensity: 0.4, depthWrite: false }), [cx, -0.12, cz], [0, 0, 0], "nocol"); sm.userData.noLift = true; sm.userData.flat = 1; sm.renderOrder = 1; sm.name = "water";
