  const isl = (x, z, r) => { const g = new THREE.SphereGeometry(r, 24, 10, 0, TAU, 0, Math.PI / 2); g.scale(1, 0.18, 1); const m = add(g, thM("islS", () => std({ color: "#f2e6c8", roughness: 1 })), [x, -0.3, z], [0, 0, 0], "nocol"); m.userData.noLift = true; const j = new THREE.SphereGeometry(r * 0.6, 16, 8, 0, TAU, 0, Math.PI / 2); j.scale(1, 0.45, 1); const jm = add(j, thM("islJ", () => std({ color: "#3e8a3a", roughness: 1 })), [x, r * 0.1, z], [0, 0, 0], "nocol"); jm.userData.noLift = true; for (let k = 0; k < Math.max(3, r / 2); k++) { const a = R() * TAU, rr = r * (0.3 + R() * 0.4), G = thPalm(x + Math.cos(a) * rr, z + Math.sin(a) * rr, 5 + R() * 3); if (G) { G.position.y = r * 0.12; G.userData.noLift = true; } } };
  const spots = []; for (let k = 0; k < 400 && spots.length < 14; k++) { const a = R() * TAU, rr = 70 + R() * 170, x = cx + Math.cos(a) * rr, z = cz + Math.sin(a) * rr; if (dist(x, z) < 45 || spots.some(([sx, sz]) => Math.hypot(sx - x, sz - z) < 40)) continue; spots.push([x, z]); isl(x, z, 6 + R() * 12); }
