  if (kind === "nuts") top((x2, y2, z2) => { add(olathe([[0.001, 0], [0.2, 0], [0.24, 0.12], [0.001, 0.12]], 10), mk().M.weave, [x2, y2, z2], [0, 0, 0], null, G); add(new THREE.SphereGeometry(0.18, 8, 5, 0, TAU, 0, Math.PI / 2), std({ color: "#a8683a", roughness: 0.8 }), [x2, y2 + 0.1, z2], [0, 0, 0], null, G); });
  else if (kind === "rugs") { for (let k = 0; k < 3; k++) add(new THREE.PlaneGeometry(0.9, 1.6), D.bannerM(["#8a3a2a", "#3a6a8a", "#7a4ab0"][k]), [-0.95 + k * 0.95, 1.3, -0.9], [0, 0, 0], null, G); top((x2, y2, z2) => add(new THREE.CylinderGeometry(0.12, 0.12, 0.5, 8), D.cloth(["#c8402a", "#e8a030", "#3fc6c0"][Math.floor(R() * 3)]), [x2, y2 + 0.12, z2], [0, 0, Math.PI / 2], null, G)); }
  else if (kind === "spice") top((x2, y2, z2) => { add(olathe([[0.001, 0], [0.17, 0], [0.2, 0.18], [0.001, 0.2]], 8), D.cloth("#d8c8a0"), [x2, y2, z2], [0, 0, 0], null, G); add(new THREE.SphereGeometry(0.15, 8, 5, 0, TAU, 0, Math.PI / 2), D.cloth(["#c8402a", "#e8a030", "#8a5a2a", "#d8c070"][Math.floor(R() * 4)]), [x2, y2 + 0.18, z2], [0, 0, 0], null, G); });
  else if (kind === "copper") top((x2, y2, z2) => add(olathe([[0.001, 0], [0.16, 0], [0.2, 0.14], [0.12, 0.28], [0.14, 0.32], [0.001, 0.3]], 12), D.copper(), [x2, y2, z2], [0, 0, 0], null, G));
  else if (kind === "spores") top((x2, y2, z2) => { add(olathe([[0.001, 0], [0.1, 0], [0.12, 0.2], [0.07, 0.3], [0.001, 0.3]], 10), std({ color: "#c8fff0", transparent: true, opacity: 0.6, roughness: 0.1 }), [x2, y2, z2], [0, 0, 0], null, G); add(new THREE.SphereGeometry(0.06, 8, 6), MK.glowC(["#7af0ff", "#c86aff", "#9aff6a"][Math.floor(R() * 3)], 1.8), [x2, y2 + 0.12, z2], [0, 0, 0], null, G); });
  else if (kind === "melons") D.melons(x, z + 0.55, 6);
