  fxPanelBox(G, 0, 17.5, 0, 3.2, 2.0, 3.2, ["plate", "rust", "bluegrey"], { win: true }); add(new THREE.BoxGeometry(3.8, 0.2, 3.8), fr, [0, 19.6, 0], [0, 0, 0], null, G);
