        if (t === 0) { njC(cx, 1.1, cz, 0.8, 0.85, 2.2, NJ.metal(), 16); for (let j = 0; j < 4; j++) njT(cx, 0.4 + j * 0.5, cz, 0.84, 0.035, NJ.glow(j % 2 ? "#9a5aff" : "#2af0ff", 1.3)); njC(cx, 2.35, cz, 0.3, 0.5, 0.3, NJ.steel(), 12); } // capacitor stack
